    # Identify each axis-aligned green field and activate red markers inside it.
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3}
    seen = set()
    components = []
    for p in cells:
        if p in seen: continue
        stack = [p]; seen.add(p); comp=[]
        while stack:
            r,c=stack.pop(); comp.append((r,c))
            for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if q in cells and q not in seen: seen.add(q); stack.append(q)
        components.append(comp)
    for comp in components:
